        id: crypto.randomUUID(),
        kind: "undo",
        historyId: record.id,
        status: "running",
        startedAt: Date.now(),
        source: record.source,
        target: target.origin,
        targetTabId: target.tabId,
        logs: [],
        steps: record.types.slice().reverse().map((type) => ({ type, status: "pending", count: 0, skipped: 0, failed: 0, databases: 0, bytes: 0, errors: [] }))
